solutionCode:
const usuarios = {
  1: { id: 1, nome: 'Ana' },
  2: { id: 2, nome: 'Bruno' },
};

export function rotaDeUsuarios(request) {
  // Só sabemos responder GET nesta rota
  if (request.method !== 'GET') {
    return { status: 404, body: { erro: 'não encontrado' } };
  }

  // '/usuarios/1' vira ['', 'usuarios', '1'] — o id está na posição 2
  const partes = request.path.split('/');
  const id = Number(partes[2]);

  const usuario = usuarios[id];
  if (!usuario) {
    return { status: 404, body: { erro: 'não encontrado' } };
  }

  return { status: 200, body: usuario };
}
